//! Tests for decoding directly into a destination with
//! `ReadXDR::read_xdr_in_place`, as used by `Box`, `Vec` and
//! `VecM`, and as generated by `#[derive(ReadXDR)]` for structs.

use std::cell::Cell;
use std::mem::MaybeUninit;

use xdrs::serialize::reader::{ReadError, Reader};
use xdrs::{ReadXDR, VecM, read_xdr_in_place, txs};

#[derive(Debug, Clone, PartialEq, Eq, xdrs::ReadXDR, xdrs::WriteXDR)]
struct Big {
    id: u32,
    data: [u64; 600],
    tail: Vec<u8>,
}

fn big() -> Big {
    Big {
        id: 9,
        data: core::array::from_fn(|i| i as u64 * 3),
        tail: vec![1, 2, 3],
    }
}

#[test]
fn pointers_match_by_value_decode() {
    let value = big();
    let buf = txs::encode(&value).unwrap();

    let by_value: Big = txs::decode(&buf).unwrap();
    let boxed: Box<Big> = txs::decode(&buf).unwrap();

    assert_eq!(by_value, value);
    assert_eq!(*boxed, value);
}

#[test]
fn vec_and_vecm_of_structs() {
    let values = vec![big(), big(), big()];
    let buf = txs::encode(&values).unwrap();

    let v: Vec<Big> = txs::decode(&buf).unwrap();
    let m: VecM<Big, 3> = txs::decode(&buf).unwrap();
    assert_eq!(v, values);
    assert_eq!(m.0, values);
}

#[derive(Debug)]
struct InPlaceOnly<const N: usize>([u8; N]);

impl<'r, const N: usize> ReadXDR<'r> for InPlaceOnly<N> {
    fn read_xdr<R: Reader<'r>>(_r: &mut R) -> Result<Self, ReadError> {
        panic!("vector elements must be decoded in place");
    }

    fn read_xdr_in_place<'s, R: Reader<'r>>(
        r: &mut R,
        slot: &'s mut MaybeUninit<Self>,
    ) -> Result<&'s mut Self, ReadError> {
        Ok(slot.write(Self([r.read_u32()? as u8; N])))
    }
}

fn check_in_place_vec<const N: usize>(len: usize) {
    let values: Vec<u32> = (0..len).map(|i| (i % 256) as u32).collect();
    macro_rules! check {
        ($fmt:ident) => {{
            let buf = xdrs::$fmt::encode(&values).unwrap();
            let v: Vec<InPlaceOnly<N>> = xdrs::$fmt::decode(&buf).unwrap();
            let m: VecM<InPlaceOnly<N>> = xdrs::$fmt::decode(&buf).unwrap();
            for decoded in [v, m.0] {
                assert_eq!(decoded.len(), len);
                for (item, value) in decoded.iter().zip(&values) {
                    assert!(item.0.iter().all(|byte| *byte == *value as u8));
                }
            }
        }};
    }
    check!(txs);
    check!(cxs);
}

#[test]
fn vec_growth_keeps_decoding_in_place() {
    check_in_place_vec::<4096>(0);
    // Initial capacity 16, followed by several growth batches.
    check_in_place_vec::<4096>(67);
    // An element larger than the cap starts with no allocation.
    check_in_place_vec::<{ xdrs::MAX_PREALLOC_BYTES + 1 }>(3);
    // ZSTs have effectively unlimited capacity but still consume input.
    check_in_place_vec::<0>(xdrs::MAX_PREALLOC_BYTES + 3);
}

#[test]
fn derived_struct_in_place_initializes_slot() {
    let value = big();
    let buf = txs::encode(&value).unwrap();

    let mut slot = MaybeUninit::<Big>::uninit();
    let mut reader = txs::buf_reader::BufReader::new(&buf);
    let out = read_xdr_in_place(&mut reader, &mut slot).unwrap();
    assert_eq!(*out, value);
    // SAFETY: read_xdr_in_place returned Ok, so the slot is initialized.
    let value2 = unsafe { slot.assume_init() };
    assert_eq!(value2, value);
}

#[derive(Debug, PartialEq, Eq, xdrs::ReadXDR)]
struct Tuple(u32, [u8; 3], u64);

#[test]
fn tuple_struct() {
    let buf = txs::encode(&(5u32, [7u8, 8, 9], 11u64)).unwrap();
    let out: Box<Tuple> = txs::decode(&buf).unwrap();
    assert_eq!(*out, Tuple(5, [7, 8, 9], 11));
}

#[derive(Debug, PartialEq, Eq)]
struct Wrapper(u32);

impl From<u32> for Wrapper {
    fn from(v: u32) -> Self {
        Wrapper(v + 1)
    }
}

#[derive(Debug, PartialEq, Eq, xdrs::ReadXDR)]
struct WithVia {
    a: u32,
    #[xdr(via = "u32")]
    b: Wrapper,
    c: u32,
}

#[test]
fn via_field() {
    let buf = txs::encode(&(1u32, 2u32, 3u32)).unwrap();
    let out: Box<WithVia> = txs::decode(&buf).unwrap();
    assert_eq!(
        *out,
        WithVia {
            a: 1,
            b: Wrapper(3),
            c: 3
        }
    );
}

#[derive(Clone, Copy, xdrs::ReadXDR)]
#[repr(C, packed)]
struct Packed {
    a: [u8; 4],
    b: u64,
}

#[test]
fn packed_struct_falls_back_to_by_value() {
    let buf = txs::encode(&([1u8, 2, 3, 4], 5u64)).unwrap();
    let out: Box<Packed> = txs::decode(&buf).unwrap();
    let Packed { a, b } = *out;
    assert_eq!(a, [1, 2, 3, 4]);
    assert_eq!(b, 5);
}

#[derive(Debug, PartialEq, Eq, xdrs::ReadXDR)]
struct Unit;

#[test]
fn unit_struct() {
    let out: Box<Unit> = txs::decode(&[]).unwrap();
    assert_eq!(*out, Unit);
}

// ---- drop on error ---------------------------------------------------------

std::thread_local! {
    static LIVE: Cell<usize> = const { Cell::new(0) };
}

/// Decodes from a u32, failing on 999, and counts live instances.
#[derive(Debug)]
struct Tracked(#[allow(dead_code)] u32);

impl Drop for Tracked {
    fn drop(&mut self) {
        LIVE.set(LIVE.get() - 1);
    }
}

impl<'r> ReadXDR<'r> for Tracked {
    fn read_xdr<R: Reader<'r>>(r: &mut R) -> Result<Self, ReadError> {
        let v = r.read_u32()?;
        if v == 999 {
            return Err(ReadError::bad_discriminator(999));
        }
        if v == 998 {
            panic!("tracked decode panic");
        }
        LIVE.set(LIVE.get() + 1);
        Ok(Tracked(v))
    }
}

#[derive(Debug, xdrs::ReadXDR)]
struct ThreeTracked {
    a: Tracked,
    b: [Tracked; 2],
    c: Tracked,
}

#[test]
fn failed_field_drops_earlier_fields() {
    LIVE.set(0);

    // a, then the array's first element, then a failure in the array.
    let buf = txs::encode(&(1u32, 2u32, 999u32, 4u32)).unwrap();
    assert!(txs::decode::<Box<ThreeTracked>>(&buf).is_err());
    assert_eq!(LIVE.get(), 0);

    // Everything but the last field.
    let buf = txs::encode(&(1u32, 2u32, 3u32, 999u32)).unwrap();
    assert!(txs::decode::<Box<ThreeTracked>>(&buf).is_err());
    assert_eq!(LIVE.get(), 0);

    // Success, then drop.
    let buf = txs::encode(&(1u32, 2u32, 3u32, 4u32)).unwrap();
    let out: Box<ThreeTracked> = txs::decode(&buf).unwrap();
    assert_eq!(LIVE.get(), 4);
    drop(out);
    assert_eq!(LIVE.get(), 0);
}

#[test]
fn failed_vec_element_drops_earlier_elements() {
    LIVE.set(0);

    let buf = txs::encode(&vec![1u32, 2, 3, 999]).unwrap();
    assert!(txs::decode::<Vec<Tracked>>(&buf).is_err());
    assert_eq!(LIVE.get(), 0);
    assert!(txs::decode::<VecM<Tracked, 8>>(&buf).is_err());
    assert_eq!(LIVE.get(), 0);
}

#[test]
fn failed_element_past_prealloc_cap_drops_earlier_elements() {
    // Reach a partially initialized batch after multiple vector growths.
    let cap = xdrs::MAX_PREALLOC_BYTES / core::mem::size_of::<Tracked>();
    let len = cap * 2 + 3;

    let mut ok: Vec<u32> = vec![0; len];
    let buf = txs::encode(&ok).unwrap();
    LIVE.set(0);
    let v: VecM<Tracked, { u32::MAX }> = txs::decode(&buf).unwrap();
    assert_eq!(LIVE.get(), len);
    drop(v);
    assert_eq!(LIVE.get(), 0);

    *ok.last_mut().unwrap() = 999;
    let buf = txs::encode(&ok).unwrap();
    assert!(txs::decode::<Vec<Tracked>>(&buf).is_err());
    assert_eq!(LIVE.get(), 0);
    assert!(txs::decode::<VecM<Tracked, { u32::MAX }>>(&buf).is_err());
    assert_eq!(LIVE.get(), 0);

    *ok.last_mut().unwrap() = 998;
    let buf = txs::encode(&ok).unwrap();
    assert!(std::panic::catch_unwind(|| txs::decode::<Vec<Tracked>>(&buf)).is_err());
    assert_eq!(LIVE.get(), 0);
    assert!(std::panic::catch_unwind(|| txs::decode::<VecM<Tracked>>(&buf)).is_err());
    assert_eq!(LIVE.get(), 0);
}

// ---- incorrect implementations ----------------------------------------------

/// Returns a reference to a leaked value instead of initializing the slot.
#[cfg(debug_assertions)]
#[derive(Debug)]
struct Misplaced(#[allow(dead_code)] u8);

#[cfg(debug_assertions)]
impl<'r> ReadXDR<'r> for Misplaced {
    fn read_xdr<R: Reader<'r>>(_r: &mut R) -> Result<Self, ReadError> {
        Ok(Misplaced(0))
    }

    fn read_xdr_in_place<'s, R: Reader<'r>>(
        _r: &mut R,
        _slot: &'s mut MaybeUninit<Self>,
    ) -> Result<&'s mut Self, ReadError> {
        Ok(Box::leak(Box::new(Misplaced(0))))
    }
}

#[test]
#[cfg(debug_assertions)]
#[should_panic(expected = "outside its slot")]
fn misplaced_result_is_caught() {
    #[allow(dead_code)]
    #[derive(Debug, xdrs::ReadXDR)]
    struct Holder {
        a: u64,
        m: Misplaced,
    }

    let buf = txs::encode(&0u64).unwrap();
    let _ = txs::decode::<Box<Holder>>(&buf);
}
